"""Demo 1: Central graph construction and the degree identity."""
from __future__ import annotations
from itertools import combinations
from typing import Dict, List, Set, Tuple

Edge = Tuple[int, int]


def norm(u: int, w: int) -> Edge:
    return (u, w) if u < w else (w, u)


def central_graph(n: int, edges: Set[Edge]) -> Tuple[int, Set[Edge], Dict[Edge, int]]:
    """Return (num_vertices, edges, subdivision map) of C(G)."""
    sorted_edges = sorted(edges)
    sub: Dict[Edge, int] = {e: n + i for i, e in enumerate(sorted_edges)}
    new: Set[Edge] = set()
    for (u, w) in sorted_edges:                    # subdivide each edge
        s = sub[(u, w)]
        new |= {norm(u, s), norm(s, w)}
    for u, w in combinations(range(n), 2):         # join non-adjacent pairs
        if norm(u, w) not in edges:
            new.add((u, w))
    return n + len(sorted_edges), new, sub


def degree(edges: Set[Edge], v: int) -> int:
    return sum(1 for (a, b) in edges if v in (a, b))


if __name__ == "__main__":
    n = 5
    g = {norm(i, (i + 1) % n) for i in range(n)}   # C_5
    cn, ce, sub = central_graph(n, g)
    print(f"C(C_5): {cn} vertices, {len(ce)} edges")
    print("original-vertex degrees:", {degree(ce, v) for v in range(n)}, "= |V|-1 =", n - 1)
    print("subdivision-vertex degrees:", {degree(ce, s) for s in sub.values()})

"""Demo 2: Certified lower bounds for chi''_a(C(G)) across regular graphs."""
from __future__ import annotations
from itertools import combinations
from typing import Optional, Set, Tuple

Edge = Tuple[int, int]


def norm(u: int, w: int) -> Edge:
    return (u, w) if u < w else (w, u)


def regular_degree(n: int, edges: Set[Edge]) -> Optional[int]:
    degs = {sum(1 for (a, b) in edges if v in (a, b)) for v in range(n)}
    return next(iter(degs)) if len(degs) == 1 else None


def bounds(n: int, edges: Set[Edge]) -> dict:
    d = regular_degree(n, edges)
    if d is None:
        raise ValueError("not regular")
    if len(edges) == n * (n - 1) // 2:
        raise ValueError("complete graph")
    return {"d": d, "|V|": n, "d+3": d + 3, "|V|+1": n + 1,
            "best": max(d + 3, n + 1)}


def cycle(n: int) -> Set[Edge]:
    return {norm(i, (i + 1) % n) for i in range(n)}


def cocktail(m: int) -> Set[Edge]:
    matching = {norm(2 * i, 2 * i + 1) for i in range(m // 2)}
    return {norm(u, w) for u, w in combinations(range(m), 2)} - matching


if __name__ == "__main__":
    for k in (5, 6, 7, 8):
        print(f"C_{k}:", bounds(k, cycle(k)))
    for m in (4, 6, 8):
        print(f"K_{m}-matching:", bounds(m, cocktail(m)))

"""Demo 3: Brute-force verification of the obstruction on a tiny central graph."""
from __future__ import annotations
from itertools import combinations
from typing import Dict, FrozenSet, List, Set, Tuple

Edge = Tuple[int, int]


def norm(u: int, w: int) -> Edge:
    return (u, w) if u < w else (w, u)


def central(n: int, edges: Set[Edge]) -> Tuple[int, Set[Edge]]:
    se = sorted(edges)
    sub = {e: n + i for i, e in enumerate(se)}
    new: Set[Edge] = set()
    for (u, w) in se:
        s = sub[(u, w)]
        new |= {norm(u, s), norm(s, w)}
    for u, w in combinations(range(n), 2):
        if norm(u, w) not in edges:
            new.add((u, w))
    return n + len(se), new


def conflicts(n: int, edges: Set[Edge]) -> Dict[object, Set[object]]:
    el: List[object] = list(range(n)) + list(edges)
    c: Dict[object, Set[object]] = {x: set() for x in el}
    def add(x: object, y: object) -> None:
        c[x].add(y); c[y].add(x)
    for (u, w) in edges:
        add(u, w)
    for e in edges:
        add(e[0], e); add(e[1], e)
    for e, f in combinations(edges, 2):
        if set(e) & set(f):
            add(e, f)
    return c


def color_set(col: Dict[object, int], edges: Set[Edge], v: int) -> FrozenSet[int]:
    return frozenset({col[v]} | {col[e] for e in edges if v in e})


def has_avd(n: int, edges: Set[Edge], k: int) -> bool:
    order: List[object] = list(range(n)) + list(edges)
    c = conflicts(n, edges)
    a: Dict[object, int] = {}
    def bt(i: int) -> bool:
        if i == len(order):
            return all(color_set(a, edges, u) != color_set(a, edges, w) for (u, w) in edges)
        x = order[i]
        for col in range(k):
            if all(a.get(y) != col for y in c[x]):
                a[x] = col
                if bt(i + 1):
                    return True
                del a[x]
        return False
    return bt(0)


if __name__ == "__main__":
    n = 4
    g = {norm(i, (i + 1) % n) for i in range(n)}    # C_4, extremal for d=2
    cn, ce = central(n, g)
    for k in (3, 4, 5):
        print(f"AVD-total colouring of C(C_4) with {k} colours:", has_avd(cn, ce, k))

