from __future__ import annotations
from itertools import combinations
from typing import Dict, Set, Tuple

Edge = Tuple[int, int]


def norm(u: int, w: int) -> Edge:
    return (u, w) if u < w else (w, u)


def build_central_graph(n: int, edges: Set[Edge]) -> Tuple[int, Set[Edge], Dict[Edge, int]]:
    """Construct C(G): subdivide every edge, join every non-adjacent pair.

    Returns (number of vertices, edge set, map original-edge -> subdivision vertex).
    Runs in O(n^2) time (the complement scan dominates).
    """
    sorted_edges = sorted(edges)
    subdivision: Dict[Edge, int] = {e: n + i for i, e in enumerate(sorted_edges)}
    out: Set[Edge] = set()
    for (u, w) in sorted_edges:
        s = subdivision[(u, w)]
        out.add(norm(u, s))
        out.add(norm(s, w))
    for u, w in combinations(range(n), 2):
        if norm(u, w) not in edges:
            out.add((u, w))
    return n + len(sorted_edges), out, subdivision

from __future__ import annotations
from typing import Optional, Set, Tuple

Edge = Tuple[int, int]


def certified_lower_bound(n: int, edges: Set[Edge]) -> int:
    """Best certified lower bound for chi''_a(C(G)) of a regular non-complete G.

    Returns max(d+3, |V|+1) = |V|+1, since |V| >= d+2 for non-complete regular G.
    Raises ValueError if G is not regular or is complete.
    """
    degs = {sum(1 for (a, b) in edges if v in (a, b)) for v in range(n)}
    if len(degs) != 1:
        raise ValueError("graph is not regular")
    d = next(iter(degs))
    if len(edges) == n * (n - 1) // 2:
        raise ValueError("graph is complete (no non-adjacent pair)")
    return max(d + 3, n + 1)

from __future__ import annotations
from itertools import combinations
from typing import Dict, FrozenSet, List, Set, Tuple

Edge = Tuple[int, int]


def verify_avd_total(coloring: Dict[object, int], n: int, edges: Set[Edge]) -> bool:
    """Verify that ``coloring`` is a proper total colouring that is AVD.

    Elements are vertices 0..n-1 and edge tuples. Runs in O(V + E) up to set ops:
    one properness pass over total-graph conflicts, one distinguishing pass over
    edges comparing colour sets.
    """
    def color_set(v: int) -> FrozenSet[int]:
        return frozenset({coloring[v]} | {coloring[e] for e in edges if v in e})

    # properness: vertex-vertex, vertex-edge, edge-edge
    for (u, w) in edges:
        if coloring[u] == coloring[w]:
            return False
    for e in edges:
        if coloring[e] in (coloring[e[0]], coloring[e[1]]):
            return False
    for e, f in combinations(edges, 2):
        if set(e) & set(f) and coloring[e] == coloring[f]:
            return False
    # adjacent-vertex-distinguishing
    for (u, w) in edges:
        if color_set(u) == color_set(w):
            return False
    return True
